 1| /**
 2|  * price-line: prices the current line and adds it to the running totals.
 3|  *
 4|  * The rule: ten or more of one item take 5% off that line. A line's total is
 5|  * rounded to the cent once, after the discount.
 6|  * Example: 11 × NOTE-A5 at 3.33 → 11 × 3.33 × 0.95 = 34.7985 → `lineTotal = 34.8`.
 7|  */
 8| import { CATALOG } from '../../data/catalog.mjs';
 9| import { roundCents, roundGrams } from '../../money.mjs';
10| 
11| export const purpose = 'Price the current line (bulk discount) and add it to the totals.';
12| 
13| /** Quantity from which a line gets the bulk discount. */
14| const BULK_QTY = 10;
15| /** The bulk discount, as a share of the line. */
16| const BULK_RATE = 0.05;
17| 
18| /** @param {any} scope */
19| export function run(scope) {
20|   const line = scope.lines[scope.lineIndex];
21|   const item = CATALOG[line.sku];
22|   if (!item) throw new Error(`unknown item ${line.sku}`);
23|   const rate = line.qty >= BULK_QTY ? BULK_RATE : 0;
24|   const lineTotal = roundCents(line.qty * item.price * (1 - rate));
25|   scope.pricedLines = [...scope.pricedLines, { sku: line.sku, qty: line.qty, unitPrice: item.price, lineTotal }];
26|   scope.subtotal = roundCents(scope.subtotal + lineTotal);
27|   scope.totalWeight = roundGrams(scope.totalWeight + line.qty * item.weightKg);
28|   scope.linesLeft = scope.lineCount - scope.lineIndex - 1;
29| }
